# ---------------------------------------------------------------------------
# Concurrency and Thread Safety Tests
# ---------------------------------------------------------------------------
class TestConcurrency:
    """Tests for thread safety and concurrent execution."""

    def test_concurrent_executions(self, runtime, mock_subprocess_run):
        """Verify multiple concurrent executions work correctly."""
        results = []
        errors = []

        def run_container():
            try:
                result = runtime.run_container(
                    image="ubuntu:latest",
                    command=["echo", "test"],
                )
                results.append(result)
            except Exception as e:
                errors.append(e)

        threads = []
        for _ in range(10):
            thread = threading.Thread(target=run_container)
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

        assert len(results) == 10
        assert len(errors) == 0
        assert mock_subprocess_run.call_count == 10

    def test_thread_safety_of_runtime_state(self, runtime, mock_subprocess_run):
        """Verify runtime maintains thread-safe state."""
        runtime._container_count = 0

        def increment_count():
            for _ in range(100):
                runtime._container_count += 1

        threads = [threading.Thread(target=increment_count) for _ in range(5)]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()

        # Note: This test may fail if _container_count is not thread-safe
        # It's designed to expose race conditions
        assert runtime._container_count == 500


