# ---------------------------------------------------------------------------
# Error Recovery Tests
# ---------------------------------------------------------------------------
class TestErrorRecovery:
    """Tests for error recovery and resilience."""

    def test_recovery_after_failure(self, runtime, mock_subprocess_run):
        """Verify runtime recovers after a failure."""
        # First call fails
        mock_subprocess_run.side_effect = [
            subprocess.TimeoutExpired(cmd=["podman", "run"], timeout=300),
            MagicMock(stdout="success", stderr="", returncode=0),
        ]
        
        with pytest.raises(ContainerExecutionError):
            runtime.run_container(
                image="ubuntu:latest",
                command=["sleep", "1000"],
            )
        
        # Second call succeeds
        result = runtime.run_container(
            image="ubuntu:latest",
            command=["echo", "success"],
        )
        
        assert result.success is True
        assert result.stdout == "success"

    def test_partial_failure_recovery(self, runtime, mock_subprocess_run):
        """Verify runtime handles partial failures in batch operations."""
        results = []
        
        def run_with_failure():
            try:
                result = runtime.run_container(
                    image="ubuntu:latest",
                    command=["echo", "test"],
                )
                results.append(result)
            except ContainerExecutionError:
                results.append(None)
        
        # Simulate 3 failures out of 10
        mock_subprocess_run.side_effect = [
            subprocess.TimeoutExpired(cmd=["podman", "run"], timeout=300)
            if i % 3 == 0
            else MagicMock(stdout="success", stderr="", returncode=0)
            for i in range(10)
        ]
        
        for _ in range(10):
            run_with_failure()
        
        assert len(results) == 10
        assert results.count(None) == 3  # 3 failures
        assert sum(1 for r in results if r and r.success) == 7  # 7 successes


